package com.materialchecklist;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MaterialChecklistPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MaterialChecklistPlugin.class);
		RuneLite.main(args);
	}
}

package com.materialchecklist;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/** Validates the bundled wiki-generated recipes.json. */
public class RecipeBookTest
{
	private static RecipeBook book;

	@BeforeClass
	public static void load()
	{
		Gson gson = new GsonBuilder().create();
		book = new RecipeBook(gson);
	}

	@Test
	public void datasetIsLarge()
	{
		assertTrue("expected > 4500 recipes, got " + book.size(), book.size() > 4500);
	}

	@Test
	public void knownRecipesResolve()
	{
		Recipe moltenGlass = book.get("Molten glass (Normal furnace)");
		assertNotNull(moltenGlass);
		assertEquals(1775, moltenGlass.productId);
		assertEquals(2, moltenGlass.ingredients().size());
		// soda ash 1781 + bucket of sand 1783
		assertTrue(moltenGlass.ingredients().stream().anyMatch(i -> i.itemId == 1781 && i.quantity == 1));
		assertTrue(moltenGlass.ingredients().stream().anyMatch(i -> i.itemId == 1783 && i.quantity == 1));

		// steel bar default method should include iron ore (440)
		Recipe steelBar = book.defaultFor(2353);
		assertNotNull(steelBar);
		assertTrue(steelBar.ingredients().stream().anyMatch(i -> i.itemId == 440));
	}

	@Test
	public void searchRanksExactAndPrefixFirst()
	{
		List<Recipe> results = book.search("molten glass", 10);
		assertFalse(results.isEmpty());
		assertTrue(results.get(0).name.toLowerCase().startsWith("molten glass"));
	}

	@Test
	public void rawDataIsWellFormed() throws Exception
	{
		try (InputStream in = RecipeBook.class.getResourceAsStream("recipes.json"))
		{
			assertNotNull("recipes.json must be bundled", in);
			JsonObject root = new JsonParser().parse(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			JsonArray recipes = root.getAsJsonArray("recipes");
			Set<String> names = new HashSet<>();
			for (int i = 0; i < recipes.size(); i++)
			{
				JsonObject recipe = recipes.get(i).getAsJsonObject();
				String name = recipe.get("name").getAsString();
				assertFalse("empty name at index " + i, name.isEmpty());
				assertTrue("duplicate name: " + name, names.add(name.toLowerCase()));
				int productId = recipe.get("productId").getAsInt();
				JsonArray ingredients = recipe.getAsJsonArray("ingredients");
				assertTrue("no ingredients: " + name, ingredients.size() > 0);
				for (int j = 0; j < ingredients.size(); j++)
				{
					JsonObject ingredient = ingredients.get(j).getAsJsonObject();
					int itemId = ingredient.get("itemId").getAsInt();
					int quantity = ingredient.get("quantity").getAsInt();
					assertTrue("bad ingredient id in " + name, itemId > 0);
					assertTrue("bad quantity in " + name, quantity > 0);
					assertFalse("recipe consumes its own product: " + name, productId > 0 && itemId == productId);
					if (ingredient.has("same"))
					{
						JsonArray same = ingredient.getAsJsonArray("same");
						for (int k = 0; k < same.size(); k++)
						{
							assertFalse("interchangeable-id set contains the recipe's own product: " + name,
								productId > 0 && same.get(k).getAsInt() == productId);
						}
					}
				}
			}
		}
	}
}

package com.materialchecklist;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(ChecklistState.CONFIG_GROUP)
public interface MaterialChecklistConfig extends Config
{
	@ConfigSection(
		name = "Counting",
		description = "What counts toward the materials you own",
		position = 0
	)
	String countingSection = "counting";

	@ConfigSection(
		name = "Materials view",
		description = "How the aggregated materials list is displayed",
		position = 1
	)
	String materialsSection = "materials";

	@ConfigSection(
		name = "Adding from the game",
		description = "Ways to add finished goods without the search box",
		position = 2
	)
	String addingSection = "adding";

	enum AddMenuMode
	{
		ALWAYS("Always"),
		SHIFT("Hold Shift"),
		DISABLED("Disabled");

		private final String label;

		AddMenuMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum FarmingYield
	{
		AVERAGE("Typical average"),
		MINIMUM("Guaranteed minimum");

		private final String label;

		FarmingYield(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum MaterialSort
	{
		MISSING_FIRST("Missing first"),
		MOST_NEEDED("Most needed"),
		ALPHABETICAL("Alphabetical");

		private final String label;

		MaterialSort(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "includeBank",
		name = "Count banked items",
		description = "Include your bank (snapshotted whenever you open it) when counting owned materials",
		section = countingSection,
		position = 0
	)
	default boolean includeBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "deductOwnedProducts",
		name = "Owned products reduce needs",
		description = "Finished goods you already own count toward a goal, reducing how many to make and the materials for them. Off: materials always cover making the full wanted amount.",
		section = countingSection,
		position = 1
	)
	default boolean countOwnedProducts()
	{
		return false;
	}

	@ConfigItem(
		keyName = "farmingYield",
		name = "Variable crop yields",
		description = "Seeds for variable-yield crops assume a typical harvest (~3x the guaranteed minimum, e.g. ~10 hemp per 3-seed planting) or the worst-case guaranteed minimum",
		section = countingSection,
		position = 2
	)
	default FarmingYield farmingYield()
	{
		return FarmingYield.AVERAGE;
	}

	@ConfigItem(
		keyName = "autoRemoveOwned",
		name = "Auto-remove finished goods",
		description = "Remove a finished good from the checklist once you own the wanted amount",
		section = countingSection,
		position = 3
	)
	default boolean autoRemoveCompleted()
	{
		return true;
	}

	@ConfigItem(
		keyName = "removeWhenBuilt",
		name = "Remove goods when built",
		description = "Building or applying a tracked part or furniture piece ticks one off the checklist (boat parts, POH furniture and other buildables never enter your inventory, so ownership can't detect them)",
		section = countingSection,
		position = 4
	)
	default boolean removeWhenBuilt()
	{
		return true;
	}

	@ConfigItem(
		keyName = "materialSort",
		name = "Sort materials by",
		description = "Order of the aggregated materials list",
		section = materialsSection,
		position = 0
	)
	default MaterialSort materialSort()
	{
		return MaterialSort.MISSING_FIRST;
	}

	@ConfigItem(
		keyName = "hideCompleted",
		name = "Hide completed materials",
		description = "Hide materials you already have enough of from the Materials tab",
		section = materialsSection,
		position = 1
	)
	default boolean hideCompleted()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showPrices",
		name = "Show GE cost of missing materials",
		description = "Show the Grand Exchange cost to buy what you are still missing",
		section = materialsSection,
		position = 2
	)
	default boolean showPrices()
	{
		return true;
	}

	@ConfigItem(
		keyName = "skillGuideMenu",
		name = "Skill guide right-click",
		description = "Add 'Add to Checklist' to right-click menus in the skill guides",
		section = addingSection,
		position = 0
	)
	default boolean skillGuideMenu()
	{
		return true;
	}

	@ConfigItem(
		keyName = "itemMenuMode",
		name = "Inventory/bank right-click",
		description = "Add 'Add to Checklist' to right-click menus on craftable inventory and bank items",
		section = addingSection,
		position = 1
	)
	default AddMenuMode itemMenuMode()
	{
		return AddMenuMode.SHIFT;
	}

	@ConfigItem(
		keyName = "buildMenuAdd",
		name = "Capture build menu clicks",
		description = "Clicking an entry in the POH furniture or ship customisation menus adds it to the checklist",
		section = addingSection,
		position = 2
	)
	default boolean buildMenuAdd()
	{
		return true;
	}

	@ConfigItem(
		keyName = "buildMenuRequireShift",
		name = "Only while holding Shift",
		description = "Capture build menu clicks only while Shift is held, so ordinary building does not fill the checklist",
		section = addingSection,
		position = 3
	)
	default boolean buildMenuRequireShift()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatMessageOnAdd",
		name = "Chat message on add",
		description = "Show a chat message when something is added from the game",
		section = addingSection,
		position = 4
	)
	default boolean chatMessageOnAdd()
	{
		return true;
	}

	@ConfigItem(
		keyName = "openPanelOnAdd",
		name = "Open panel on add",
		description = "Open the Material Checklist side panel when something is added from the game",
		section = addingSection,
		position = 5
	)
	default boolean openPanelOnAdd()
	{
		return true;
	}
}

package com.materialchecklist;

import java.util.List;

/**
 * Immutable view model handed from the client thread to the EDT.
 * Everything the panel renders comes from here; the only live references
 * are the {@link Goal} nodes used to route panel actions back to state.
 */
public class ChecklistSnapshot
{
	/** Goods view: one entry per root goal. */
	public final List<GoalLine> goals;
	/** Materials view: aggregated raw materials across every goal. */
	public final List<MaterialLine> totals;
	/** GE cost of everything still missing (0 when prices are disabled). */
	public final long missingCost;
	public final boolean hasBankSnapshot;

	public ChecklistSnapshot(List<GoalLine> goals, List<MaterialLine> totals, long missingCost, boolean hasBankSnapshot)
	{
		this.goals = goals;
		this.totals = totals;
		this.missingCost = missingCost;
		this.hasBankSnapshot = hasBankSnapshot;
	}

	/** One aggregated raw material. */
	public static class MaterialLine
	{
		public final int itemId;
		public final String name;
		public final int needed;
		public final int inventory;
		public final int bank;
		/** A recipe exists for this material, so it can be drilled into. */
		public final boolean craftable;
		/** GE cost of the missing amount (0 when prices disabled or untradeable). */
		public final long missingCost;

		public MaterialLine(int itemId, String name, int needed, int inventory, int bank, boolean craftable, long missingCost)
		{
			this.itemId = itemId;
			this.name = name;
			this.needed = needed;
			this.inventory = inventory;
			this.bank = bank;
			this.craftable = craftable;
			this.missingCost = missingCost;
		}

		public int have()
		{
			return inventory + bank;
		}

		public int missing()
		{
			return Math.max(0, needed - have());
		}
	}

	/** A goal (root finished good, or an expanded intermediate). */
	public static class GoalLine
	{
		/** Live state node — used for panel callbacks; do not mutate directly. */
		public final Goal goal;
		/** Null when the recipe vanished from a regenerated dataset. */
		public final Recipe recipe;
		/** Wanted units (roots: goal quantity; children: derived from parent). */
		public final int units;
		/** Finished products already owned (inventory + bank). */
		public final int owned;
		public final boolean collapsed;
		/** Validated icon item id (0 = none); some product items have no sprite. */
		public final int iconItemId;
		/** Required-tools note for the tooltip ("" when none); tools are never counted as materials. */
		public final String toolsText;
		public final List<MaterialRow> rows;

		public GoalLine(Goal goal, Recipe recipe, int units, int owned, boolean collapsed, int iconItemId, String toolsText, List<MaterialRow> rows)
		{
			this.goal = goal;
			this.recipe = recipe;
			this.units = units;
			this.owned = owned;
			this.collapsed = collapsed;
			this.iconItemId = iconItemId;
			this.toolsText = toolsText;
			this.rows = rows;
		}
	}

	/** One ingredient row beneath a goal. */
	public static class MaterialRow
	{
		public final MaterialLine line;
		/** The goal this row belongs to (live reference, for expand/collapse). */
		public final Goal parentGoal;
		/** Set when the user expanded this material into its own recipe. */
		public final GoalLine child;

		public MaterialRow(MaterialLine line, Goal parentGoal, GoalLine child)
		{
			this.line = line;
			this.parentGoal = parentGoal;
			this.child = child;
		}

		public boolean expanded()
		{
			return child != null;
		}
	}
}

package com.materialchecklist;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.Skill;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.Text;

/**
 * In-game entry points for adding finished goods to the checklist.
 *
 * Skill guides get a real right-click menu entry. Most skill-guide entries
 * have no vanilla menu ops (only Magic/Construction/Sailing do), so
 * MenuEntryAdded never identifies the hovered row — instead we hook
 * MenuOpened and hit-test the mouse against the guide's row widgets. Both
 * guide versions are handled: the legacy parchment guide (group 214) and the
 * modern one (group 860, four dynamic children per row). Entries use
 * MenuAction.RUNELITE with an onClick consumer, so clicking runs purely
 * client-side and nothing is sent to the server.
 *
 * The POH furniture and ship customisation menus must NOT get injected menu
 * entries (hub rule) — those are covered by passively observing shift-clicks.
 */
@Slf4j
@Singleton
public class GameMenuSupport
{
	private static final String ADD_OPTION = "Add to Checklist";

	private final Client client;
	private final ItemManager itemManager;
	private final RecipeBook recipeBook;
	private final MaterialChecklistConfig config;

	/** Set by the plugin at startUp; receives the recipe chosen in-game. */
	private Consumer<Recipe> onAdd;

	/** Receives the candidate recipe names when a tracked thing is built. */
	private Consumer<Collection<String>> onBuilt;

	private List<Integer> buildInterfaces;

	@Inject
	GameMenuSupport(Client client, ItemManager itemManager, RecipeBook recipeBook, MaterialChecklistConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.recipeBook = recipeBook;
		this.config = config;
	}

	void init(Consumer<Recipe> onAdd, Consumer<Collection<String>> onBuilt)
	{
		this.onAdd = onAdd;
		this.onBuilt = onBuilt;
		buildInterfaces = Arrays.asList(
			InterfaceID.POH_FURNITURE_CREATION,
			InterfaceID.POH_FURNITURE_CREATION_MENU,
			InterfaceID.SAILING_CUSTOMISATION,
			InterfaceID.SAILING_BOAT_SELECTION,
			InterfaceID.SAILING_BT_SELECTION,
			InterfaceID.SAILING_MENU
		);
	}

	/** Client thread. */
	void onMenuOpened(MenuOpened event)
	{
		if (!config.skillGuideMenu() || onAdd == null)
		{
			return;
		}
		Point mouse = client.getMouseCanvasPosition();

		// Modern skill guide (group 860): rows are 4 dynamic children on LIST:
		// [row rect, level text, item graphic, description text]. Rows scrolled
		// out of the viewport keep canvas bounds outside the list, so gate the
		// whole test on the mouse being inside the list container first.
		Widget list = client.getWidget(InterfaceID.SkillGuideV2.LIST);
		if (list != null && !list.isHidden() && containsOrDegenerate(list, mouse))
		{
			Widget[] children = list.getDynamicChildren();
			for (int i = 0; i + 3 < children.length; i += 4)
			{
				if (children[i + 2] != null && hit(children[i], mouse))
				{
					offerEntry(children[i + 2], children[i + 3], InterfaceID.SKILL_GUIDE_V2);
					return;
				}
			}
			log.debug("skill guide v2: no row hit at {},{} ({} children)",
				mouse.getX(), mouse.getY(), children.length);
		}

		// Legacy skill guide (group 214): icon child i on ICONS, text children
		// 2i (level) / 2i+1 (description) on INFO
		Widget icons = client.getWidget(InterfaceID.SkillGuide.ICONS);
		Widget info = client.getWidget(InterfaceID.SkillGuide.INFO);
		if (icons != null && !icons.isHidden() && info != null)
		{
			if (!containsOrDegenerate(icons, mouse) && !containsOrDegenerate(info, mouse))
			{
				log.debug("legacy skill guide: gate rejected mouse {},{} (icons {} info {})",
					mouse.getX(), mouse.getY(), icons.getBounds(), info.getBounds());
				return;
			}
			Widget[] iconChildren = icons.getDynamicChildren();
			for (int i = 0; i < iconChildren.length; i++)
			{
				if (iconChildren[i] == null)
				{
					continue;
				}
				if (hit(iconChildren[i], mouse)
					|| hit(info.getChild(i * 2), mouse)
					|| hit(info.getChild(i * 2 + 1), mouse))
				{
					offerEntry(iconChildren[i], info.getChild(i * 2 + 1), InterfaceID.SKILL_GUIDE);
					return;
				}
			}
			log.debug("legacy skill guide: no row hit at {},{} ({} icon children)",
				mouse.getX(), mouse.getY(), iconChildren.length);
		}
	}

	/** True when the mouse is inside the widget's bounds. */
	private static boolean hit(Widget widget, Point mouse)
	{
		return widget != null && widget.getBounds().contains(mouse.getX(), mouse.getY());
	}

	/**
	 * Container gate for scroll clipping. Some layer widgets report zero-size
	 * bounds even though their children render — a degenerate container must
	 * not veto the row hit-test, so it passes.
	 */
	private static boolean containsOrDegenerate(Widget container, Point mouse)
	{
		Rectangle bounds = container.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return true;
		}
		return bounds.contains(mouse.getX(), mouse.getY());
	}

	private void offerEntry(Widget iconWidget, Widget descriptionWidget, int guideInterfaceId)
	{
		int itemId = iconWidget.getItemId();
		// -1 = sprite-override rows; BLANKOBJECT = invisible dummy rows
		if (itemId <= 0 || itemId == ItemID.BLANKOBJECT)
		{
			log.debug("skill guide row has no usable item id ({})", itemId);
			return;
		}
		int canonical = itemManager.canonicalize(itemId);
		String itemName = itemManager.getItemComposition(canonical).getMembersName();
		String rowText = "";
		if (descriptionWidget != null && descriptionWidget.getText() != null)
		{
			// guide rows are often two lines ("Strength potion<br>Tarromin &
			// limpwurt root") — only the first line names the unlock
			String firstLine = descriptionWidget.getText().split("<br\\s*/?>", 2)[0];
			rowText = Text.removeTags(firstLine).trim();
		}

		Map<String, Recipe> union = new LinkedHashMap<>();
		// The row's text names the actual unlock — Herblore rows show the
		// SECONDARY ingredient's icon while the text names the potion, so the
		// text takes precedence over the icon item.
		if (!rowText.isEmpty())
		{
			putAll(union, recipeBook.candidatesFor(0, rowText));
			// guide rows often pluralize ("Willow trees") — retry singular
			if (union.isEmpty() && rowText.endsWith("s"))
			{
				putAll(union, recipeBook.candidatesFor(0, rowText.substring(0, rowText.length() - 1)));
			}
		}
		putAll(union, candidatesWithChain(canonical, itemName));
		List<Recipe> candidates = new ArrayList<>(union.values());

		// The guide's skill is the strongest hint of intent: browsing the
		// Farming guide and clicking Ranarr means seeds, not herb cleaning.
		String guideSkill = detectGuideSkill(guideInterfaceId);
		candidates = filterBySkill(candidates, guideSkill);

		if (candidates.isEmpty())
		{
			// pure-ingredient rows (Herblore secondaries): offer what the item
			// makes — but inside a guide, ONLY that skill's recipes; a Yew tree
			// row in the Farming guide must not surface Fletching recipes
			candidates = new ArrayList<>();
			for (Recipe consumer : consumersIncludingVariants(canonical))
			{
				if (guideSkill == null || guideSkill.equalsIgnoreCase(consumer.skill))
				{
					candidates.add(consumer);
				}
			}
			if (candidates.size() > 15)
			{
				log.debug("guide entry '{}' used by {} recipes — too ambiguous to offer", itemName, candidates.size());
				return;
			}
		}
		if (candidates.isEmpty())
		{
			log.debug("no recipe for guide entry '{}' / text '{}' (item {} canonical {})",
				itemName, rowText, itemId, canonical);
			return;
		}
		candidates.sort(BY_LEVEL_THEN_NAME);
		if (candidates.size() > 10)
		{
			candidates = candidates.subList(0, 10);
		}
		attachAddEntry(canonical, JagexColors.MENU_TARGET_TAG + itemName, candidates);
	}

	private static final java.util.Comparator<Recipe> BY_LEVEL_THEN_NAME = (a, b) ->
	{
		int cmp = Integer.compare(a.level, b.level);
		return cmp != 0 ? cmp : a.name.compareToIgnoreCase(b.name);
	};

	private static void putAll(Map<String, Recipe> union, List<Recipe> recipes)
	{
		for (Recipe recipe : recipes)
		{
			union.putIfAbsent(recipe.name.toLowerCase(), recipe);
		}
	}

	/** Keeps only recipes of the given skill when any match; null skill keeps all. */
	private static List<Recipe> filterBySkill(List<Recipe> candidates, String skill)
	{
		if (skill == null)
		{
			return candidates;
		}
		List<Recipe> matching = new ArrayList<>();
		for (Recipe candidate : candidates)
		{
			if (skill.equalsIgnoreCase(candidate.skill))
			{
				matching.add(candidate);
			}
		}
		return matching.isEmpty() ? candidates : matching;
	}

	/** Recipes consuming the item or any of its variants (potion doses etc.). */
	private List<Recipe> consumersIncludingVariants(int canonical)
	{
		Map<String, Recipe> union = new LinkedHashMap<>();
		putAll(union, recipeBook.consumersOf(canonical));
		for (int variant : ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical)))
		{
			putAll(union, recipeBook.consumersOf(variant));
		}
		return new ArrayList<>(union.values());
	}

	/**
	 * Direct recipes for the item, plus one step back down the chain: for a
	 * single-ingredient recipe (herb cleaning, log cutting...) the recipes
	 * producing that ingredient are offered too, so a clean herb can resolve
	 * to growing the grimy one from seed.
	 */
	private List<Recipe> candidatesWithChain(int canonical, String name)
	{
		List<Recipe> direct = recipeBook.candidatesFor(canonical, name);
		if (direct.isEmpty())
		{
			// dose/charge variants: a (4)-dose icon should still find the (3)-dose recipe
			direct = new ArrayList<>();
			for (int variant : ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical)))
			{
				direct.addAll(recipeBook.producersOf(variant));
			}
		}
		Map<String, Recipe> union = new LinkedHashMap<>();
		for (Recipe recipe : direct)
		{
			union.put(recipe.name.toLowerCase(), recipe);
		}
		for (Recipe recipe : direct)
		{
			if (recipe.ingredients().size() == 1)
			{
				for (Recipe producer : recipeBook.producersOf(recipe.ingredients().get(0).itemId))
				{
					union.putIfAbsent(producer.name.toLowerCase(), producer);
				}
			}
		}
		List<Recipe> candidates = new ArrayList<>(union.values());
		candidates.sort((a, b) ->
		{
			int cmp = Integer.compare(a.level, b.level);
			return cmp != 0 ? cmp : a.name.compareToIgnoreCase(b.name);
		});
		return candidates.size() > 10 ? candidates.subList(0, 10) : candidates;
	}

	/**
	 * Reads the open guide's skill from its title text (e.g. "Sailing" or
	 * "Farming Guide"). Null when no title matches a skill name — candidates
	 * are then left unfiltered.
	 */
	private String detectGuideSkill(int guideInterfaceId)
	{
		for (int child = 0; child < 60; child++)
		{
			Widget widget = client.getWidget(WidgetUtil.packComponentId(guideInterfaceId, child));
			if (widget == null)
			{
				continue;
			}
			String skill = skillNameIn(widget.getText());
			if (skill != null)
			{
				return skill;
			}
			Widget[] dynamicChildren = widget.getDynamicChildren();
			if (dynamicChildren != null)
			{
				for (Widget kid : dynamicChildren)
				{
					skill = kid == null ? null : skillNameIn(kid.getText());
					if (skill != null)
					{
						return skill;
					}
				}
			}
			Widget[] staticChildren = widget.getStaticChildren();
			if (staticChildren != null)
			{
				for (Widget kid : staticChildren)
				{
					skill = kid == null ? null : skillNameIn(kid.getText());
					if (skill != null)
					{
						return skill;
					}
				}
			}
		}
		return null;
	}

	private static String skillNameIn(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}
		String cleaned = Text.removeTags(text).trim();
		for (Skill skill : Skill.values())
		{
			if (cleaned.equalsIgnoreCase(skill.getName())
				|| cleaned.equalsIgnoreCase(skill.getName() + " Guide"))
			{
				return skill.getName();
			}
		}
		return null;
	}

	/**
	 * Creates the "Add to Checklist" entry. A single production method adds
	 * directly; multiple methods expand into a submenu so the user picks the
	 * variant (e.g. Mithril keel (Skiff) vs (Sloop)) before anything is added.
	 */
	private void attachAddEntry(int canonicalId, String target, List<Recipe> candidates)
	{
		MenuEntry parent = client.getMenu().createMenuEntry(-1)
			.setOption(ADD_OPTION)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.setItemId(canonicalId);
		if (candidates.size() == 1)
		{
			Recipe only = candidates.get(0);
			parent.onClick(e -> onAdd.accept(only));
			return;
		}
		Menu subMenu = parent.createSubMenu();
		for (Recipe variant : candidates)
		{
			subMenu.createMenuEntry(0)
				.setOption("Add")
				.setTarget(JagexColors.MENU_TARGET_TAG + variant.name)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> onAdd.accept(variant));
		}
	}

	/** Client thread; fires per entry per frame — keep cheap. */
	void onMenuEntryAdded(MenuEntryAdded event)
	{
		MaterialChecklistConfig.AddMenuMode mode = config.itemMenuMode();
		if (mode == MaterialChecklistConfig.AddMenuMode.DISABLED
			|| (mode == MaterialChecklistConfig.AddMenuMode.SHIFT && !client.isKeyPressed(KeyCode.KC_SHIFT))
			|| onAdd == null || !"Examine".equals(event.getOption()))
		{
			return;
		}
		int component = event.getActionParam1();
		if (component != InterfaceID.Bankmain.ITEMS && component != InterfaceID.Inventory.ITEMS)
		{
			return;
		}
		int itemId = event.getItemId();
		if (itemId <= 0)
		{
			return;
		}
		int canonical = itemManager.canonicalize(itemId);
		List<Recipe> candidates = candidatesWithChain(canonical, null);
		if (candidates.isEmpty())
		{
			return;
		}
		attachAddEntry(canonical, event.getTarget(), candidates);
	}

	/**
	 * Client thread. Passive observation of POH furniture / ship
	 * customisation menus: shift-clicks add a tracked thing, plain clicks
	 * with a build verb tick one off (built parts never enter the inventory,
	 * so ownership-based removal cannot see them).
	 */
	void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (onAdd == null)
		{
			return;
		}
		int interfaceId = WidgetUtil.componentToInterface(event.getParam1());
		if (!buildInterfaces.contains(interfaceId))
		{
			return;
		}
		int itemId = event.getMenuEntry().getItemId();
		if (itemId <= 0)
		{
			Widget widget = event.getMenuEntry().getWidget();
			if (widget != null)
			{
				itemId = widget.getItemId();
			}
		}
		int canonical = itemId > 0 ? itemManager.canonicalize(itemId) : 0;
		String target = event.getMenuTarget() == null ? "" : Text.removeTags(event.getMenuTarget()).trim();

		boolean shiftHeld = client.isKeyPressed(KeyCode.KC_SHIFT);
		if (config.buildMenuAdd() && (shiftHeld || !config.buildMenuRequireShift()))
		{
			Recipe recipe = canonical > 0 ? recipeBook.defaultFor(canonical) : null;
			if (recipe == null && !target.isEmpty())
			{
				recipe = recipeBook.bestForProductName(target);
			}
			if (recipe != null)
			{
				onAdd.accept(recipe);
			}
			return;
		}

		if (config.removeWhenBuilt() && onBuilt != null && isBuildVerb(event.getMenuOption()))
		{
			Set<String> names = new LinkedHashSet<>();
			if (canonical > 0)
			{
				for (Recipe producer : recipeBook.producersOf(canonical))
				{
					names.add(producer.name);
				}
			}
			if (!target.isEmpty())
			{
				for (Recipe candidate : recipeBook.candidatesFor(0, target))
				{
					names.add(candidate.name);
				}
			}
			if (!names.isEmpty())
			{
				onBuilt.accept(names);
			}
		}
	}

	private static boolean isBuildVerb(String option)
	{
		if (option == null)
		{
			return false;
		}
		String lower = option.toLowerCase();
		return lower.startsWith("build") || lower.startsWith("apply") || lower.startsWith("craft")
			|| lower.startsWith("create") || lower.startsWith("make") || lower.startsWith("attach");
	}
}

package com.materialchecklist;

import com.google.inject.Provides;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Material Checklist",
	description = "Plan items to craft across all skills and track the raw materials you still need, counting inventory and bank",
	tags = {"materials", "checklist", "crafting", "smithing", "fletching", "herblore", "construction", "skilling", "shopping", "bank"}
)
public class MaterialChecklistPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private RecipeBook recipeBook;

	@Inject
	private ChecklistState state;

	@Inject
	private OwnedItems owned;

	@Inject
	private ChecklistCalculator calculator;

	@Inject
	private GameMenuSupport gameMenus;

	@Inject
	private MaterialChecklistConfig config;

	@Inject
	private EventBus eventBus;

	private MaterialChecklistPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		panel = new MaterialChecklistPanel(this, recipeBook, itemManager);
		gameMenus.init(this::addFromGame, this::builtFromGame);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Material Checklist")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				owned.loadBankSnapshot();
				owned.updateInventory(client.getItemContainer(InventoryID.INV));
			}
			refresh();
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

	@Provides
	MaterialChecklistConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MaterialChecklistConfig.class);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			owned.updateInventory(event.getItemContainer());
			refresh();
		}
		else if (event.getContainerId() == InventoryID.BANK)
		{
			owned.updateBank(event.getItemContainer());
			refresh();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			owned.loadBankSnapshot();
			refresh();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// logged out: the live inventory tally no longer applies (and must
			// not bleed into a different account's counts on the next login)
			owned.clearInventory();
			refresh();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// RuneLite config profile switched: the goals key now points at a
		// different profile's data — reload rather than overwriting it
		state.reload();
		refresh();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invoke(() ->
		{
			owned.loadBankSnapshot();
			refresh();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ChecklistState.CONFIG_GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(this::refresh);
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		gameMenus.onMenuOpened(event);
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		gameMenus.onMenuEntryAdded(event);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		gameMenus.onMenuOptionClicked(event);
	}

	/**
	 * Recomputes the snapshot on the client thread and hands it to the panel.
	 * Safe to call from any thread.
	 */
	public void refresh()
	{
		clientThread.invoke(() ->
		{
			if (panel == null)
			{
				return;
			}
			GameState gameState = client.getGameState();
			if (gameState == GameState.STARTING || gameState == GameState.UNKNOWN)
			{
				// item cache not loaded yet; a later GameStateChanged will retry
				return;
			}
			autoRemoveCompletedGoals();
			ChecklistSnapshot snapshot = calculator.build();
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.render(snapshot);
				}
			});
		});
	}

	/** Client thread. Removes root goals whose wanted amount is now owned. */
	private void autoRemoveCompletedGoals()
	{
		if (!config.autoRemoveCompleted())
		{
			return;
		}
		java.util.List<Goal> completed = state.read(goals ->
		{
			java.util.List<Goal> done = new java.util.ArrayList<>();
			for (Goal goal : goals)
			{
				Recipe recipe = recipeBook.get(goal.name);
				if (recipe == null || recipe.productId <= 0)
				{
					continue;
				}
				int ownedCount = owned.inventoryCount(recipe.productId)
					+ (config.includeBank() ? owned.bankCount(recipe.productId) : 0);
				if (ownedCount >= goal.quantity)
				{
					done.add(goal);
				}
			}
			return done;
		});
		for (Goal goal : completed)
		{
			state.removeGoal(goal);
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.addChatMessage(ChatMessageType.CONSOLE, "",
					"Checklist complete: <col=1e9e00>" + goal.quantity + " x " + goal.name + "</col> — removed.", null);
			}
		}
	}

	/** Called from GameMenuSupport on the client thread: a tracked thing was built. */
	private void builtFromGame(java.util.Collection<String> recipeNames)
	{
		ChecklistState.BuiltResult result = state.consumeBuilt(recipeNames);
		if (result == null)
		{
			return;
		}
		client.addChatMessage(ChatMessageType.CONSOLE, "", result.remaining > 0
			? "Built <col=cc8400>" + result.name + "</col> — " + result.remaining + " left on the Material Checklist."
			: "Built <col=cc8400>" + result.name + "</col> — removed from the Material Checklist.", null);
		refresh();
	}

	/** Called from GameMenuSupport on the client thread. */
	private void addFromGame(Recipe recipe)
	{
		state.addGoal(recipe.name, 1);
		if (config.chatMessageOnAdd())
		{
			client.addChatMessage(ChatMessageType.CONSOLE, "",
				"Added <col=cc8400>" + recipe.name + "</col> to the Material Checklist.", null);
		}
		if (config.openPanelOnAdd())
		{
			final NavigationButton button = navButton;
			if (button != null)
			{
				// openPanel must run on the EDT; this handler is on the client thread
				SwingUtilities.invokeLater(() -> clientToolbar.openPanel(button));
			}
		}
		refresh();
	}

	// ---- panel callbacks (EDT) ----

	public void addGoal(String recipeName, int quantity)
	{
		state.addGoal(recipeName, quantity);
		refresh();
	}

	public void removeGoal(Goal goal)
	{
		state.removeGoal(goal);
		refresh();
	}

	public void setGoalQuantity(Goal goal, int quantity)
	{
		state.setQuantity(goal, quantity);
		refresh();
	}

	public void toggleCollapsed(Goal goal)
	{
		state.toggleCollapsed(goal);
		refresh();
	}

	public void expandMaterial(Goal parent, int itemId)
	{
		Recipe recipe = recipeBook.defaultFor(itemId);
		if (recipe != null)
		{
			state.expandMaterial(parent, recipe.name);
			refresh();
		}
	}

	public void collapseMaterial(Goal parent, String childRecipeName)
	{
		state.collapseMaterial(parent, childRecipeName);
		refresh();
	}

	/** Switches a goal to another production method, pruning drill-downs the new method lacks. */
	public void changeGoalMethod(Goal goal, Recipe newRecipe)
	{
		state.changeMethod(goal, newRecipe.name);
		for (Goal child : new java.util.ArrayList<>(goal.children()))
		{
			Recipe childRecipe = recipeBook.get(child.name);
			boolean stillUsed = childRecipe != null && childRecipe.productId > 0
				&& newRecipe.ingredients().stream().anyMatch(i -> i.allIds().contains(childRecipe.productId));
			if (!stillUsed)
			{
				state.collapseMaterial(goal, child.name);
			}
		}
		refresh();
	}

	public void clearChecklist()
	{
		state.clear();
		refresh();
	}

	/** Promotes a material to its own root goal (the user plans to craft it). */
	public void addMaterialAsGoal(int itemId, int quantity)
	{
		Recipe recipe = recipeBook.defaultFor(itemId);
		if (recipe != null)
		{
			state.addGoal(recipe.name, quantity);
			refresh();
		}
	}

	/**
	 * Opens this plugin's page in the RuneLite settings sidebar. There is no
	 * public API for this; the established hub pattern (Watchdog and others)
	 * is a synthetic overlay-config menu click, which ConfigPlugin handles by
	 * opening the poster plugin's configuration. Fails silently if RuneLite
	 * ever stops handling it.
	 */
	public void openConfiguration()
	{
		eventBus.post(new OverlayMenuClicked(
			new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, null, null),
			new ConfigLinkOverlay(this)));
	}

	private static class ConfigLinkOverlay extends Overlay
	{
		ConfigLinkOverlay(Plugin plugin)
		{
			super(plugin);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			return null;
		}
	}
}

package com.materialchecklist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One production recipe from the bundled wiki-generated dataset.
 * The recipe NAME is the primary key everywhere (search, persistence,
 * drill-down); {@code productId} is 0 for buildable scenery (POH furniture
 * variants and the like) that has no backing item.
 */
public class Recipe
{
	public String name;
	public int productId;
	public String skill;
	public int level;
	public int makes;
	/** Farming crops whose harvest varies; {@code makes} is the guaranteed minimum. */
	public boolean variableYield;
	public List<Ingredient> ingredients;
	/** Required tool item ids (needed once, not per batch); may include consumed one-offs. */
	public List<Integer> tools;

	public List<Integer> tools()
	{
		return tools == null ? Collections.emptyList() : tools;
	}

	public int batchSize()
	{
		return Math.max(1, makes);
	}

	/** Number of times the recipe must be performed to yield {@code wanted} products. */
	public int batchesFor(int wanted)
	{
		int batch = batchSize();
		return (wanted + batch - 1) / batch;
	}

	/** Item id used for the panel icon; scenery borrows the first ingredient's icon. */
	public int iconItemId()
	{
		if (productId > 0)
		{
			return productId;
		}
		return ingredients == null || ingredients.isEmpty() ? 0 : ingredients.get(0).itemId;
	}

	public List<Ingredient> ingredients()
	{
		return ingredients == null ? Collections.emptyList() : ingredients;
	}

	public static class Ingredient
	{
		public int itemId;
		public int quantity;
		public List<Integer> same;

		/** The canonical id plus any interchangeable ids (e.g. watered saplings). */
		public List<Integer> allIds()
		{
			if (same == null || same.isEmpty())
			{
				return Collections.singletonList(itemId);
			}
			List<Integer> ids = new ArrayList<>(1 + same.size());
			ids.add(itemId);
			ids.addAll(same);
			return ids;
		}
	}
}

package com.materialchecklist;

import com.materialchecklist.ChecklistSnapshot.GoalLine;
import com.materialchecklist.ChecklistSnapshot.MaterialLine;
import com.materialchecklist.ChecklistSnapshot.MaterialRow;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;

/**
 * Builds a {@link ChecklistSnapshot} from the goal tree, recipe book and
 * owned-item counts. Must run on the CLIENT THREAD — it resolves item names
 * from the game cache.
 *
 * Two passes over the goal tree: the first walks every goal allocating owned
 * finished/intermediate products (greedy, tree order) and accumulating raw
 * requirements; the second builds view lines using the completed allocation
 * ledger, so items counted as an owned product are not double-counted as
 * owned raw materials elsewhere.
 */
@Singleton
public class ChecklistCalculator
{
	/** Cycle guard for pathological recipe chains. */
	private static final int MAX_DEPTH = 8;

	private final ChecklistState state;
	private final RecipeBook recipeBook;
	private final OwnedItems owned;
	private final ItemManager itemManager;
	private final MaterialChecklistConfig config;

	private final Map<Integer, String> nameCache = new ConcurrentHashMap<>();

	@Inject
	ChecklistCalculator(ChecklistState state, RecipeBook recipeBook, OwnedItems owned,
		ItemManager itemManager, MaterialChecklistConfig config)
	{
		this.state = state;
		this.recipeBook = recipeBook;
		this.owned = owned;
		this.itemManager = itemManager;
		this.config = config;
	}

	public ChecklistSnapshot build()
	{
		Build build = new Build();
		List<GoalLine> goalLines = state.read(goals ->
		{
			for (Goal goal : goals)
			{
				Recipe recipe = recipeBook.get(goal.name);
				if (recipe != null)
				{
					build.allocate(goal, recipe, goal.quantity, 0);
				}
			}
			List<GoalLine> lines = new ArrayList<>(goals.size());
			for (Goal goal : goals)
			{
				Recipe recipe = recipeBook.get(goal.name);
				if (recipe == null)
				{
					// dataset regenerated and the name vanished; keep it visible so
					// the user can remove it rather than silently dropping data
					lines.add(new GoalLine(goal, null, goal.quantity, 0, goal.collapsed, 0, "", new ArrayList<>()));
					continue;
				}
				lines.add(build.lines(goal, recipe, 0));
			}
			return lines;
		});

		List<MaterialLine> totals = new ArrayList<>(build.rawNeeded.size());
		long totalMissingCost = 0;
		for (Map.Entry<Integer, Integer> entry : build.rawNeeded.entrySet())
		{
			if (entry.getValue() <= 0)
			{
				continue;
			}
			MaterialLine line = build.materialLine(entry.getKey(), entry.getValue(),
				build.rawAlternates.get(entry.getKey()), true);
			totalMissingCost += line.missingCost;
			if (config.hideCompleted() && line.missing() == 0)
			{
				continue;
			}
			totals.add(line);
		}
		totals.sort(comparatorFor(config.materialSort()));
		return new ChecklistSnapshot(goalLines, totals, totalMissingCost, owned.hasBankSnapshot());
	}

	private static java.util.Comparator<MaterialLine> comparatorFor(MaterialChecklistConfig.MaterialSort sort)
	{
		java.util.Comparator<MaterialLine> byName = (a, b) -> a.name.compareToIgnoreCase(b.name);
		switch (sort)
		{
			case ALPHABETICAL:
				return byName;
			case MOST_NEEDED:
				return java.util.Comparator.comparingInt((MaterialLine l) -> -l.needed).thenComparing(byName);
			case MISSING_FIRST:
			default:
				return java.util.Comparator.comparingInt((MaterialLine l) -> -l.missing()).thenComparing(byName);
		}
	}

	/** Per-build accumulators and the two tree passes. */
	private class Build
	{
		final Map<Integer, Integer> rawNeeded = new LinkedHashMap<>();
		final Map<Integer, List<Integer>> rawAlternates = new HashMap<>();
		/** Owned products consumed by goals, by product item id. */
		final Map<Integer, Integer> allocatedProducts = new HashMap<>();
		/** Pass-one numbers per goal node: {wantedUnits, ownedUsed, batches}. */
		final Map<Goal, int[]> nodeNumbers = new IdentityHashMap<>();

		/** Pass one: allocate owned products and accumulate raw requirements. */
		void allocate(Goal goal, Recipe recipe, int wantedUnits, int depth)
		{
			int ownedUsed = 0;
			if (config.countOwnedProducts() && recipe.productId > 0)
			{
				int have = countOwned(recipe.productId);
				int alreadyAllocated = allocatedProducts.getOrDefault(recipe.productId, 0);
				ownedUsed = Math.min(Math.max(0, have - alreadyAllocated), wantedUnits);
				if (ownedUsed > 0)
				{
					allocatedProducts.merge(recipe.productId, ownedUsed, Integer::sum);
				}
			}
			int unitsToMake = wantedUnits - ownedUsed;
			int batches = unitsToMake <= 0 ? 0 : effectiveBatchesFor(recipe, unitsToMake);
			nodeNumbers.put(goal, new int[]{wantedUnits, ownedUsed, batches});

			for (Recipe.Ingredient ingredient : recipe.ingredients())
			{
				int required = batches * ingredient.quantity;
				// The Materials tab tracks the DIRECT ingredients of the goods
				// the user added; expanding a material in the Goods view is
				// informational and never rewrites the shopping list.
				if (depth == 0 && required > 0)
				{
					rawNeeded.merge(ingredient.itemId, required, Integer::sum);
					if (ingredient.same != null && !ingredient.same.isEmpty())
					{
						rawAlternates.put(ingredient.itemId, ingredient.same);
					}
				}
				Goal childGoal = depth < MAX_DEPTH ? findChild(goal, ingredient) : null;
				if (childGoal != null)
				{
					allocate(childGoal, recipeBook.get(childGoal.name), required, depth + 1);
				}
			}
		}

		/** Pass two: build view lines with the completed allocation ledger. */
		GoalLine lines(Goal goal, Recipe recipe, int depth)
		{
			int[] numbers = nodeNumbers.get(goal);
			int wantedUnits = numbers[0];
			int ownedUsed = numbers[1];
			int batches = numbers[2];

			List<MaterialRow> rows = new ArrayList<>(recipe.ingredients().size());
			for (Recipe.Ingredient ingredient : recipe.ingredients())
			{
				int required = batches * ingredient.quantity;
				Goal childGoal = depth < MAX_DEPTH ? findChild(goal, ingredient) : null;
				if (childGoal != null)
				{
					GoalLine childLine = lines(childGoal, recipeBook.get(childGoal.name), depth + 1);
					// the expanded row shows full owned counts; the child line's
					// own allocation already accounts for what is consumed
					MaterialLine line = materialLine(ingredient.itemId, required, ingredient.same, false);
					rows.add(new MaterialRow(line, goal, childLine));
				}
				else
				{
					MaterialLine line = materialLine(ingredient.itemId, required, ingredient.same, true);
					rows.add(new MaterialRow(line, goal, null));
				}
			}
			// tools (saw, hammer, persistent one-offs like wind motes) are NOT
			// materials — they surface only as a note in the goal tooltip
			StringBuilder toolsText = new StringBuilder();
			for (int toolId : recipe.tools())
			{
				if (toolsText.length() > 0)
				{
					toolsText.append(", ");
				}
				toolsText.append(nameOf(toolId));
			}
			return new GoalLine(goal, recipe, wantedUnits, ownedUsed, goal.collapsed,
				iconFor(recipe), toolsText.toString(), rows);
		}

		private Goal findChild(Goal goal, Recipe.Ingredient ingredient)
		{
			for (Goal child : goal.children())
			{
				Recipe childRecipe = recipeBook.get(child.name);
				if (childRecipe != null && childRecipe.productId > 0
					&& ingredient.allIds().contains(childRecipe.productId))
				{
					return child;
				}
			}
			return null;
		}

		/**
		 * Builds one material line. When {@code subtractAllocations} is set,
		 * owned units already allocated to goals as finished products are
		 * removed from the displayed counts (bank first, then inventory) so
		 * the same physical items are never counted twice.
		 */
		MaterialLine materialLine(int itemId, int needed, List<Integer> alternates, boolean subtractAllocations)
		{
			List<Integer> ids = new ArrayList<>();
			ids.add(itemId);
			if (alternates != null)
			{
				ids.addAll(alternates);
			}
			int inv = 0;
			int bank = 0;
			int allocated = 0;
			for (int id : ids)
			{
				inv += owned.inventoryCount(id);
				if (config.includeBank())
				{
					bank += owned.bankCount(id);
				}
				if (subtractAllocations)
				{
					allocated += allocatedProducts.getOrDefault(id, 0);
				}
			}
			int fromBank = Math.min(bank, allocated);
			bank -= fromBank;
			inv = Math.max(0, inv - (allocated - fromBank));

			String name = nameOf(itemId);
			boolean craftable = recipeBook.hasRecipeFor(itemId);
			long missingCost = 0;
			int missing = Math.max(0, needed - inv - bank);
			if (config.showPrices() && missing > 0)
			{
				missingCost = (long) itemManager.getItemPrice(itemId) * missing;
			}
			return new MaterialLine(itemId, name, needed, inv, bank, craftable, missingCost);
		}

		private int countOwned(int itemId)
		{
			return countOwned(Collections.singletonList(itemId));
		}

		private int countOwned(List<Integer> ids)
		{
			int total = 0;
			for (int id : ids)
			{
				total += owned.inventoryCount(id);
				if (config.includeBank())
				{
					total += owned.bankCount(id);
				}
			}
			return total;
		}
	}

	/**
	 * Batches (plantings) needed for the wanted units. Variable-yield crops
	 * record the guaranteed minimum per planting; under the typical-yield
	 * assumption (~3.3x, e.g. ~10 hemp instead of 3 per 3-seed planting)
	 * far fewer plantings are assumed.
	 */
	private int effectiveBatchesFor(Recipe recipe, int units)
	{
		int perBatch = recipe.batchSize();
		if (recipe.variableYield
			&& config.farmingYield() == MaterialChecklistConfig.FarmingYield.AVERAGE)
		{
			perBatch = Math.max(perBatch, (int) Math.round(perBatch * 10.0 / 3.0));
		}
		return (units + perBatch - 1) / perBatch;
	}

	/**
	 * Icon item for a goal header. Some wiki-sourced product ids (notably
	 * Sailing part combos) have no usable sprite in the client cache — those
	 * resolve to a "null" composition name; fall back to an ingredient's icon.
	 */
	private int iconFor(Recipe recipe)
	{
		int id = recipe.iconItemId();
		if (id > 0 && !"null".equalsIgnoreCase(nameOf(id)))
		{
			return id;
		}
		for (Recipe.Ingredient ingredient : recipe.ingredients())
		{
			if (!"null".equalsIgnoreCase(nameOf(ingredient.itemId)))
			{
				return ingredient.itemId;
			}
		}
		return id;
	}

	/** Client thread; memoized. Uses getMembersName to avoid " (Members)" suffixes on F2P worlds. */
	private String nameOf(int itemId)
	{
		return nameCache.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getMembersName());
	}
}

package com.materialchecklist;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The user's goal list plus persistence. Mutations may come from the EDT
 * (panel actions) and the client thread (menu clicks); the view model holds
 * live {@link Goal} references and every access goes through this monitor,
 * so mutations can use identity.
 */
@Slf4j
@Singleton
public class ChecklistState
{
	static final String CONFIG_GROUP = "materialchecklist";
	private static final String GOALS_KEY = "goals";

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<Goal> goals = new ArrayList<>();

	@Inject
	ChecklistState(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		load();
	}

	/** Re-reads goals from config — call when the RuneLite config profile switches. */
	synchronized void reload()
	{
		goals.clear();
		load();
	}

	private void load()
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, GOALS_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			List<Goal> loaded = gson.fromJson(json, new TypeToken<List<Goal>>()
			{
			}.getType());
			if (loaded != null)
			{
				for (Goal goal : loaded)
				{
					if (goal != null && goal.name != null && goal.quantity > 0)
					{
						goals.add(goal);
					}
				}
			}
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Could not parse saved goals", e);
		}
	}

	private void save()
	{
		configManager.setConfiguration(CONFIG_GROUP, GOALS_KEY, gson.toJson(goals));
	}

	/** Runs {@code fn} over the live goal list while holding the state lock. */
	public synchronized <T> T read(Function<List<Goal>, T> fn)
	{
		return fn.apply(goals);
	}

	public synchronized boolean isEmpty()
	{
		return goals.isEmpty();
	}

	/** Adds quantity to an existing root goal for the recipe, or creates one. */
	public synchronized void addGoal(String recipeName, int quantity)
	{
		for (Goal goal : goals)
		{
			if (goal.name.equalsIgnoreCase(recipeName))
			{
				goal.quantity += quantity;
				save();
				return;
			}
		}
		goals.add(new Goal(recipeName, quantity));
		save();
	}

	public synchronized void removeGoal(Goal target)
	{
		if (goals.removeIf(g -> g == target))
		{
			save();
		}
	}

	public synchronized void setQuantity(Goal target, int quantity)
	{
		if (goals.contains(target) && quantity > 0)
		{
			target.quantity = quantity;
			save();
		}
	}

	public synchronized void toggleCollapsed(Goal target)
	{
		target.collapsed = !target.collapsed;
		save();
	}

	/** Marks an ingredient of {@code parent} as "craft this" by adding a child goal. */
	public synchronized void expandMaterial(Goal parent, String childRecipeName)
	{
		for (Goal child : parent.children())
		{
			if (child.name.equalsIgnoreCase(childRecipeName))
			{
				return;
			}
		}
		parent.children().add(new Goal(childRecipeName, 0));
		save();
	}

	/**
	 * Switches a goal to a different production method (recipe) for the same
	 * product, keeping its quantity, collapse state and children.
	 */
	public synchronized void changeMethod(Goal target, String newRecipeName)
	{
		target.name = newRecipeName;
		save();
	}

	/** Reverts an expanded ingredient back to a raw material. */
	public synchronized void collapseMaterial(Goal parent, String childRecipeName)
	{
		if (parent.children().removeIf(c -> c.name.equalsIgnoreCase(childRecipeName)))
		{
			save();
		}
	}

	public synchronized void clear()
	{
		goals.clear();
		save();
	}

	/** Outcome of ticking off a built goal. */
	public static class BuiltResult
	{
		public final String name;
		public final int remaining;

		BuiltResult(String name, int remaining)
		{
			this.name = name;
			this.remaining = remaining;
		}
	}

	/**
	 * The player built one of the named recipes in-game: decrement the
	 * matching root goal, removing it at zero. Null when nothing matched.
	 */
	public synchronized BuiltResult consumeBuilt(java.util.Collection<String> recipeNames)
	{
		for (Goal goal : goals)
		{
			for (String name : recipeNames)
			{
				if (goal.name.equalsIgnoreCase(name))
				{
					if (goal.quantity > 1)
					{
						goal.quantity--;
						save();
						return new BuiltResult(goal.name, goal.quantity);
					}
					goals.remove(goal);
					save();
					return new BuiltResult(goal.name, 0);
				}
			}
		}
		return null;
	}
}

package com.materialchecklist;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the bundled recipes.json (generated from the OSRS Wiki by
 * tools/generate_recipes.py) and indexes it by name and product item id.
 */
@Slf4j
@Singleton
public class RecipeBook
{
	private final Map<String, Recipe> byName = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
	private final Map<Integer, List<Recipe>> byProductId = new HashMap<>();
	private final Map<Integer, List<Recipe>> byIngredient = new HashMap<>();

	private static class RecipeFile
	{
		String generated;
		String source;
		@SerializedName("recipes")
		List<Recipe> recipes;
	}

	@Inject
	public RecipeBook(Gson gson)
	{
		try (InputStream in = RecipeBook.class.getResourceAsStream("recipes.json"))
		{
			if (in == null)
			{
				log.error("recipes.json missing from plugin resources");
				return;
			}
			RecipeFile file = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), RecipeFile.class);
			for (Recipe recipe : file.recipes)
			{
				if (recipe.name == null || recipe.ingredients == null || recipe.ingredients.isEmpty())
				{
					continue;
				}
				if (byName.putIfAbsent(recipe.name, recipe) != null)
				{
					continue;
				}
				if (recipe.productId > 0)
				{
					byProductId.computeIfAbsent(recipe.productId, k -> new ArrayList<>()).add(recipe);
				}
				for (Recipe.Ingredient ingredient : recipe.ingredients())
				{
					for (int id : ingredient.allIds())
					{
						byIngredient.computeIfAbsent(id, k -> new ArrayList<>()).add(recipe);
					}
				}
			}
			log.debug("Loaded {} recipes (generated {})", byName.size(), file.generated);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	public Recipe get(String name)
	{
		return name == null ? null : byName.get(name);
	}

	public boolean hasRecipeFor(int itemId)
	{
		return byProductId.containsKey(itemId);
	}

	public int size()
	{
		return byName.size();
	}

	/**
	 * The default production method for an item: fewest distinct ingredients,
	 * ties broken toward MORE total raw material (never understate a shopping
	 * list), then the shorter name.
	 */
	public Recipe defaultFor(int itemId)
	{
		List<Recipe> candidates = byProductId.get(itemId);
		if (candidates == null || candidates.isEmpty())
		{
			return null;
		}
		Recipe best = null;
		for (Recipe r : candidates)
		{
			if (best == null || compareSimplicity(r, best) < 0)
			{
				best = r;
			}
		}
		return best;
	}

	private static int compareSimplicity(Recipe a, Recipe b)
	{
		int cmp = Integer.compare(a.ingredients().size(), b.ingredients().size());
		if (cmp != 0)
		{
			return cmp;
		}
		cmp = Integer.compare(totalRaw(b), totalRaw(a));
		if (cmp != 0)
		{
			return cmp;
		}
		return Integer.compare(a.name.length(), b.name.length());
	}

	private static int totalRaw(Recipe r)
	{
		int total = 0;
		for (Recipe.Ingredient i : r.ingredients())
		{
			total += i.quantity;
		}
		return total;
	}

	/**
	 * All recipes that could be meant by a product item id / display name,
	 * for offering a method choice at add time. Prefers the product-id index;
	 * falls back to exact and "Name (variant)" name matches. Sorted by level
	 * requirement, then name.
	 */
	public List<Recipe> candidatesFor(int productId, String productName)
	{
		List<Recipe> matches = new ArrayList<>();
		List<Recipe> byId = productId > 0 ? byProductId.get(productId) : null;
		if (byId != null && !byId.isEmpty())
		{
			matches.addAll(byId);
		}
		else if (productName != null && !productName.isEmpty())
		{
			Recipe exact = byName.get(productName);
			if (exact != null)
			{
				matches.add(exact);
			}
			// both "Name (variant)" and potion-style "Name(3)" spellings
			String spaced = productName.toLowerCase() + " (";
			String unspaced = productName.toLowerCase() + "(";
			for (Map.Entry<String, Recipe> entry : byName.entrySet())
			{
				String key = entry.getKey().toLowerCase();
				if (key.startsWith(spaced) || key.startsWith(unspaced))
				{
					matches.add(entry.getValue());
				}
			}
		}
		matches.sort((a, b) ->
		{
			int cmp = Integer.compare(a.level, b.level);
			return cmp != 0 ? cmp : a.name.compareToIgnoreCase(b.name);
		});
		return matches;
	}

	/** All recipes that produce the given item (empty when none do). */
	public List<Recipe> producersOf(int itemId)
	{
		List<Recipe> list = byProductId.get(itemId);
		return list == null ? Collections.emptyList() : list;
	}

	/** All recipes that consume the given item as an ingredient. */
	public List<Recipe> consumersOf(int itemId)
	{
		List<Recipe> list = byIngredient.get(itemId);
		return list == null ? Collections.emptyList() : list;
	}

	/**
	 * All production methods for the same product as {@code recipe}
	 * (including itself). Scenery products cannot be grouped by id and
	 * return just the recipe itself.
	 */
	public List<Recipe> variantsFor(Recipe recipe)
	{
		if (recipe == null)
		{
			return Collections.emptyList();
		}
		if (recipe.productId > 0)
		{
			List<Recipe> variants = byProductId.get(recipe.productId);
			if (variants != null && variants.size() > 1)
			{
				return variants;
			}
		}
		return Collections.singletonList(recipe);
	}

	/**
	 * Finds a recipe by product display name: exact name match first, then
	 * the simplest "Name (variant)" entry. Used when a game widget's item id
	 * has no direct productId match in the dataset.
	 */
	public Recipe bestForProductName(String productName)
	{
		if (productName == null || productName.isEmpty())
		{
			return null;
		}
		Recipe exact = byName.get(productName);
		if (exact != null)
		{
			return exact;
		}
		String prefix = productName.toLowerCase() + " (";
		Recipe best = null;
		for (Map.Entry<String, Recipe> entry : byName.entrySet())
		{
			if (entry.getKey().toLowerCase().startsWith(prefix))
			{
				Recipe candidate = entry.getValue();
				if (best == null || compareSimplicity(candidate, best) < 0)
				{
					best = candidate;
				}
			}
		}
		return best;
	}

	/**
	 * Ranked substring search over recipe names: exact match first, then
	 * prefix, then contains; shorter names win ties. Cheap enough to run
	 * per keystroke on the EDT (~5k names).
	 */
	public List<Recipe> search(String query, int limit)
	{
		String needle = query == null ? "" : query.trim().toLowerCase();
		if (needle.isEmpty())
		{
			return Collections.emptyList();
		}
		List<Recipe> matches = new ArrayList<>();
		for (Map.Entry<String, Recipe> entry : byName.entrySet())
		{
			if (entry.getKey().toLowerCase().contains(needle))
			{
				matches.add(entry.getValue());
			}
		}
		matches.sort((a, b) ->
		{
			int cmp = Integer.compare(rank(a.name, needle), rank(b.name, needle));
			if (cmp != 0)
			{
				return cmp;
			}
			cmp = Integer.compare(a.name.length(), b.name.length());
			if (cmp != 0)
			{
				return cmp;
			}
			return a.name.compareToIgnoreCase(b.name);
		});
		return matches.size() > limit ? matches.subList(0, limit) : matches;
	}

	private static int rank(String name, String needle)
	{
		String lower = name.toLowerCase();
		if (lower.equals(needle))
		{
			return 0;
		}
		return lower.startsWith(needle) ? 1 : 2;
	}
}

package com.materialchecklist;

import java.util.ArrayList;
import java.util.List;

/**
 * One node of the user's checklist. Roots are finished goods with a wanted
 * quantity; children are intermediate materials the user chose to craft
 * (their needed quantity is derived from the parent at aggregation time).
 * Persisted as JSON — recipes are referenced by NAME, never by item id,
 * so buildable scenery round-trips like any other product.
 */
public class Goal
{
	public String name;
	public int quantity;
	public boolean collapsed;
	public List<Goal> children = new ArrayList<>();

	public Goal()
	{
	}

	public Goal(String name, int quantity)
	{
		this.name = name;
		this.quantity = quantity;
	}

	public List<Goal> children()
	{
		if (children == null)
		{
			children = new ArrayList<>();
		}
		return children;
	}

	public Goal copy()
	{
		Goal copy = new Goal(name, quantity);
		copy.collapsed = collapsed;
		for (Goal child : children())
		{
			copy.children.add(child.copy());
		}
		return copy;
	}
}

package com.materialchecklist;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Tracks what the player owns: a live inventory tally plus a bank snapshot
 * captured whenever the bank fires ItemContainerChanged (the only time bank
 * contents are readable) and persisted per RS profile so counts survive
 * between banking trips and sessions. All ids are canonicalized so noted
 * items and placeholders collapse onto the real item.
 *
 * Maps are replaced wholesale (never mutated) so the EDT can read them
 * without locking; updates happen on the client thread.
 */
@Slf4j
@Singleton
public class OwnedItems
{
	private static final String BANK_KEY = "bankSnapshot";

	private final ConfigManager configManager;
	private final ItemManager itemManager;

	private volatile Map<Integer, Integer> inventory = Collections.emptyMap();
	private volatile Map<Integer, Integer> bank = Collections.emptyMap();
	private String lastSavedBank = null;

	@Inject
	OwnedItems(ConfigManager configManager, ItemManager itemManager)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
	}

	/** Client thread only (canonicalize touches the item cache). */
	public void updateInventory(ItemContainer container)
	{
		inventory = tally(container);
	}

	/** Client thread only. Persists the snapshot for the active RS profile. */
	public void updateBank(ItemContainer container)
	{
		Map<Integer, Integer> tallied = tally(container);
		bank = tallied;
		String csv = toCsv(tallied);
		if (!csv.equals(lastSavedBank))
		{
			lastSavedBank = csv;
			configManager.setRSProfileConfiguration(ChecklistState.CONFIG_GROUP, BANK_KEY, csv);
		}
	}

	/** Loads the persisted bank snapshot for the current RS profile (login / profile change). */
	public void loadBankSnapshot()
	{
		String csv = configManager.getRSProfileConfiguration(ChecklistState.CONFIG_GROUP, BANK_KEY);
		bank = fromCsv(csv);
		lastSavedBank = csv;
	}

	public void clearInventory()
	{
		inventory = Collections.emptyMap();
	}

	public int inventoryCount(int itemId)
	{
		return inventory.getOrDefault(itemId, 0);
	}

	public int bankCount(int itemId)
	{
		return bank.getOrDefault(itemId, 0);
	}

	public boolean hasBankSnapshot()
	{
		return !bank.isEmpty();
	}

	private Map<Integer, Integer> tally(ItemContainer container)
	{
		if (container == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> totals = new HashMap<>();
		for (Item item : container.getItems())
		{
			int id = item.getId();
			int quantity = item.getQuantity();
			// empty slots and bank placeholders (quantity 0), plus bank fillers
			if (id <= 0 || quantity <= 0 || id == ItemID.BANK_FILLER)
			{
				continue;
			}
			totals.merge(itemManager.canonicalize(id), quantity, Integer::sum);
		}
		return totals;
	}

	private static String toCsv(Map<Integer, Integer> counts)
	{
		// sorted so identical contents always serialize identically
		// (avoids spurious config writes and cloud re-uploads)
		StringBuilder sb = new StringBuilder(counts.size() * 12);
		for (Map.Entry<Integer, Integer> entry : new TreeMap<>(counts).entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(entry.getKey()).append(',').append(entry.getValue());
		}
		return sb.toString();
	}

	private static Map<Integer, Integer> fromCsv(String csv)
	{
		if (csv == null || csv.isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> counts = new HashMap<>();
		for (String pair : csv.split(";"))
		{
			int comma = pair.indexOf(',');
			if (comma <= 0)
			{
				continue;
			}
			try
			{
				counts.put(Integer.parseInt(pair.substring(0, comma)),
					Integer.parseInt(pair.substring(comma + 1)));
			}
			catch (NumberFormatException e)
			{
				log.warn("Bad bank snapshot entry: {}", pair);
			}
		}
		return counts;
	}
}

